function walkFiberTree(root, onVisit) {
  let current = root;

  while (current) {
    onVisit(current);

    if (current.child) {
      current = current.child;
      continue;
    }

    if (current === root) break;

    while (!current.sibling) {
      if (!current.return || current.return === root) {
        return;
      }
      current = current.return;
    }

    current = current.sibling;
  }
}

