function runWorkLoop(workUnits, deadlineMs = 5) {
  const startTime = performance.now();
  let index = 0;

  while (index < workUnits.length) {
    if (performance.now() - startTime >= deadlineMs) {
      return {
        done: false,
        processedCount: index,
        remainingCount: workUnits.length - index
      };
    }
    workUnits[index]();
    index++;
  }

  return {
    done: true,
    processedCount: index,
    remainingCount: 0
  };
}
